INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('rev-1', 'Executive Director 1', 'المدير التنفيذي 1', 'Al-Jazeera Gulf Holdings W.L.L.', 'مجموعة الجزيرة الخليجية القابضة', 'Working with Zayed Group streamlined our operations and exceeded delivery expectations.', 'العمل مع مجموعة زايد ساهم في رفع كفاءة عملياتنا وتجاوز توقعاتنا في التسليم.', 5, true, 1, 2026, now() - interval '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'zayed-group-insights-1', 'Zayed Group Industry Brief #1: Enterprise Turnkey Operations Retainer', 'تقرير مجموعة زايد التخصصي #1: إدارة العمليات المؤسسية الشاملة', 'Key operational benchmarks and best practices from Zayed Group in Manama.', 'أبرز المعايير التشغيلية وأفضل الممارسات من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Our Enterprise Turnkey Operations Retainer division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. يساعد قسم إدارة العمليات المؤسسية الشاملة المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Our Enterprise Turnkey Operations Retainer division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>يساعد قسم إدارة العمليات المؤسسية الشاملة المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'all', '{"all","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage Zayed Group for a new project?', 'كيف يمكننا البدء بمشروع جديد مع مجموعة زايد؟', 'Contact Zayed Group at hello@zayedgroup.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر hello@zayedgroup.bh أو إرسال طلب إلكتروني وسيرد فريق مجموعة زايد خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
